module.exports = async (args) => {
  const streams = args.variables.ffmpegCommand.streams;
  let keptAudio = false;
  for (const s of streams) {
    if (s.codec_type !== 'audio' || s.removed) continue;
    if (keptAudio) { s.removed = true; }
    else { keptAudio = true; }
  }
  if (!keptAudio) {
    const first = streams.find((s) => s.codec_type === 'audio');
    if (first) {
      first.removed = false;
      args.jobLog('No eng/und audio survived filtering; keeping first audio track as fallback.');
    }
  }
  return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
};

// Custom JS Function node: "Extract SRT Sub"
// Position: Input File -> Copy to Working Directory -> Extract SRT Sub -> Begin Command
// Runs after Copy to Working Directory so ffmpeg reads the local cache
// copy (args.inputFileObj._id) instead of the source over the network
// share -- faster on a slow NFS/SMB link. The sidecar still gets written
// next to the real library file: the OUTPUT path is always derived from
// args.originalLibraryFile._id, which stays stable regardless of node
// position, so moving this node after the copy changes only where ffmpeg
// reads from, not where the .srt ends up.
//
// Extracts the first eligible English subtitle stream to a <basename>.eng.srt
// sidecar next to the source file. Pure side effect via its own ffmpeg
// subprocess -- does not touch args.variables.ffmpegCommand, so it has zero
// effect on the main transcode pipeline's pass count.
module.exports = async (args) => {
  const { execFile } = require('child_process');
  const fs = require('fs');

  const readPath = args.inputFileObj._id;
  const libraryPath = args.originalLibraryFile._id;
  const ffmpegPath = args.ffmpegPath || '/usr/bin/ffmpeg';

  const streams = args.inputFileObj?.ffProbeData?.streams || [];
  const engSubs = streams.filter((s) =>
    s.codec_type === 'subtitle'
    && s.tags?.language === 'eng'
    && !['hdmv_pgs_subtitle', 'dvd_subtitle', 'dvb_subtitle', 'dvb_teletext', 'xsub'].includes(s.codec_name)
    && !/commentary|description/i.test(s.tags?.title || ''));

  if (engSubs.length === 0) {
    args.jobLog('No eligible English subtitle track found.');
    return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
  }

  const chosen = engSubs.find((s) => !s.disposition?.hearing_impaired && !s.disposition?.forced) || engSubs[0];
  const outPath = libraryPath.replace(/\.[^/.]+$/, '') + '.eng.srt';

  if (fs.existsSync(outPath)) {
    args.jobLog('eng.srt already exists, skipping: ' + outPath);
    return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
  }

  await new Promise((resolve) => {
    execFile(ffmpegPath, ['-y', '-i', readPath, '-map', `0:${chosen.index}`, outPath],
      { maxBuffer: 1024 * 1024 * 20, timeout: 600000 }, (err, stdout, stderr) => {
        if (err) {
          args.jobLog('Subtitle extraction failed: ' + stderr);
          try { fs.unlinkSync(outPath); } catch (e) { /* nothing to clean up */ }
        } else {
          args.jobLog('Extracted ' + outPath);
        }
        resolve();
      });
  });

  return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
};

// Custom JS Function node: "Keep largest video track"
// Position: after Remove Data Streams, before Clean Audio Streams
// (same slot as the stock per-property removal nodes; must run after
// Begin Command and before the single final Execute).
//
// Keeps the real video stream and marks every embedded cover-art
// "attachment" stream (mjpeg posters/thumbnails, reported by Tdarr as
// codec_type: "attachment" rather than "video") removed. A real
// codec_type: "video" stream always wins over an "attachment" one,
// regardless of pixel count -- embedded poster art can be higher
// resolution than the actual movie (e.g. a 2000x3000 mjpeg cover next to
// a 1920x1080 source), so pixel count alone is not a safe comparison
// across the two types. Pixel count only breaks ties within the same
// type: multiple real video tracks, or (when no real video exists at
// all) multiple attachments.
module.exports = async (args) => {
  const streams = args.variables.ffmpegCommand.streams;
  const pixelCount = (s) => (s.width && s.height) ? s.width * s.height : 0;

  const realVideo = streams.filter((s) => s.codec_type === 'video' && pixelCount(s) > 0);
  const attachments = streams.filter((s) => s.codec_type === 'attachment' && pixelCount(s) > 0);
  // Font attachments carry no width/height and are excluded by the
  // pixelCount(s) > 0 checks above, so they're never touched.
  const videoStreams = realVideo.length > 0 ? realVideo : attachments;

  if (realVideo.length > 0) {
    for (const s of attachments) { s.removed = true; }
  }

  if (videoStreams.length > 1) {
    let largest = videoStreams[0];
    for (const s of videoStreams.slice(1)) {
      if (pixelCount(s) > pixelCount(largest)) largest = s;
    }
    const smaller = videoStreams.filter((s) => s !== largest);
    // Only ever add removals, never clear one a prior node already set.
    for (const s of smaller) { s.removed = true; }
    args.jobLog(`Kept video stream ${largest.index} (${largest.width}x${largest.height}), removed ${smaller.length} smaller video stream(s).`);
  } else if (attachments.length > 0 && realVideo.length > 0) {
    args.jobLog(`Kept real video stream, removed ${attachments.length} cover-art attachment stream(s).`);
  }

  return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
};
